examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchDataExportRequest(
    status = status,
    scope = listOf(
        MonarchDataExportScopeOption({{scope.0.id}}, {{scope.0.label}}, {{scope.0.description}}),
        MonarchDataExportScopeOption({{scope.1.id}}, {{scope.1.label}}, {{scope.1.description}}),
        MonarchDataExportScopeOption({{scope.2.id}}, {{scope.2.label}}, {{scope.2.description}}),
    ),
    formats = listOf(
        MonarchDataExportFormatOption({{formats.0.value}}, {{formats.0.label}}),
        MonarchDataExportFormatOption({{formats.1.value}}, {{formats.1.label}}),
    ),
    preparationNote = {{note}},
    onRequest = { details ->
        // The app sends details.scope and details.format to its server here.
        status = MonarchDataExportStatus.Requested
    },
)

